EMBSTR_LIMIT = 44
def encoding(val):
    s = str(val)
    if s.lstrip("-").isdigit():
        return "int"
    if len(s.encode()) <= EMBSTR_LIMIT:
        return "embstr"
    return "raw"

print("String 编码转换 (OBJ_ENCODING):")
for v in [123, "hello", "x" * 44, "x" * 45, "short"]:
    print(f"  SET k {v!r} -> {encoding(v)}")
print("  触发转换: APPEND 到 embstr 会先转 raw 再追加(embstr 只读紧凑)")
print(f"  长度44 -> {encoding('x' * 44)}; 长度45 -> {encoding('x' * 45)} (44 来自 64B jemalloc - robj16 - sdshdr8(3B) - 1B)")
